import sys; sys.path.insert(0, '_tools')
import json, subprocess
msgs = [{'jsonrpc': '2.0', 'id': 1, 'method': 'initialize', 'params': {'protocolVersion': '2025-06-18', 'capabilities': {}, 'clientInfo': {'name': 't', 'version': '0'}}},
        {'jsonrpc': '2.0', 'method': 'notifications/initialized'}, {'jsonrpc': '2.0', 'id': 2, 'method': 'tools/list', 'params': {}}]
p = subprocess.run([sys.executable, '_tools/kb_mcp.py'], input='\n'.join(json.dumps(m) for m in msgs) + '\n', capture_output=True, text=True, timeout=300)
tools = {}
for l in p.stdout.splitlines():
    try: d = json.loads(l)
    except ValueError: continue
    if d.get('id') == 2: tools = {t['name']: t for t in d['result']['tools']}
bad = [n for n in ('kb_backlog', 'kb_querylog') if (tools.get(n, {}).get('annotations') or {}).get('openWorldHint') is not True]
print('not open-world:', bad); sys.exit(1 if bad else 0)
